const items = $input.all();
const settings = $node["Workflow Settings"]?.json || {};
const maxProductsValue = Number(settings.maxProducts) || 0;
const webpQuality = Number(settings.webpQuality) || 80;

const outputs = [];
let processedProducts = 0;

for (const item of items) {
  const product = item.json || {};
  if (!product.id) continue;

  processedProducts += 1;
  if (maxProductsValue && processedProducts > maxProductsValue) break;

  const images = Array.isArray(product.images) ? product.images : [];
  for (const image of images) {
    if (!image || !image.id || !image.src) continue;
    outputs.push({
      json: {
        productId: product.id,
        productHandle: product.handle || '',
        productTitle: product.title || '',
        imageId: image.id,
        imageSrc: image.src,
        imageAlt: image.alt || '',
        webpQuality,
        originalFormat: null,
        message: null,
        isAnimated: false
      }
    });
  }
}

return outputs;

const items = $input.all();

const isAnimatedGif = (buffer) => {
  if (buffer.length < 4 || buffer.toString('ascii', 0, 3) !== 'GIF') return false;
  let frames = 0;
  for (let i = 0; i < buffer.length - 1; i++) {
    if (buffer[i] === 0x21 && buffer[i + 1] === 0xF9) {
      frames += 1;
      if (frames > 1) return true;
    }
  }
  return false;
};

const isAnimatedPng = (buffer) => {
  if (buffer.length < 8 || buffer.toString('hex', 0, 8) !== '89504e470d0a1a0a') return false;
  let offset = 8;
  while (offset + 8 < buffer.length) {
    const length = buffer.readUInt32BE(offset);
    const type = buffer.toString('ascii', offset + 4, offset + 8);
    if (type === 'acTL') return true;
    offset += 12 + length;
  }
  return false;
};

const isAnimatedWebP = (buffer) => {
  if (buffer.length < 16 || buffer.toString('ascii', 0, 4) !== 'RIFF' || buffer.toString('ascii', 8, 12) !== 'WEBP') {
    return false;
  }
  for (let i = 12; i < buffer.length - 3; i++) {
    if (
      buffer[i] === 0x41 &&
      buffer[i + 1] === 0x4E &&
      buffer[i + 2] === 0x49 &&
      buffer[i + 3] === 0x4D
    ) {
      return true;
    }
  }
  return false;
};

const detectFormat = (buffer, mimeType = '') => {
  if (mimeType) return mimeType;
  const signature = buffer.toString('hex', 0, 4);
  if (signature === 'ffd8ffe0' || signature === 'ffd8ffe1') return 'image/jpeg';
  if (signature === '89504e47') return 'image/png';
  if (buffer.toString('ascii', 0, 3) === 'GIF') return 'image/gif';
  if (buffer.toString('ascii', 0, 4) === 'RIFF') return 'image/webp';
  return 'application/octet-stream';
};

const getBinaryPayload = (binary = {}) => {
  if (binary.original?.data) {
    return { property: 'original', payload: binary.original };
  }
  const firstBinaryKey = Object.keys(binary)[0];
  if (firstBinaryKey && binary[firstBinaryKey]?.data) {
    return { property: firstBinaryKey, payload: binary[firstBinaryKey] };
  }
  return null;
};

return items.map((item) => {
  const binaryInfo = getBinaryPayload(item.binary);
  if (!binaryInfo) {
    item.json.isAnimated = true;
    item.json.message = 'Missing binary payload';
    return item;
  }

  const imageData = binaryInfo.payload;
  const buffer = Buffer.from(imageData.data, 'base64');
  const format = detectFormat(buffer, imageData.mimeType);
  const animated = isAnimatedGif(buffer) || isAnimatedPng(buffer) || isAnimatedWebP(buffer);

  item.json.isAnimated = animated;
  item.json.originalFormat = format;
  item.json.originalSizeBytes = buffer.length;
  item.json.originalBinaryProperty = binaryInfo.property;

  if (animated) {
    item.json.message = `Animated image detected (product ${item.json.productHandle || item.json.productId})`;
  }

  return item;
});

const items = $input.all();
return items.map(item => ({
  json: {
    status: 'skipped',
    reason: 'animated',
    productId: item.json.productId,
    imageId: item.json.imageId,
    message: item.json.message || 'Animated image skipped',
    productHandle: item.json.productHandle
  }
}));

const items = $input.all();
const httpRequest = this?.helpers?.httpRequest;
const getSettings = () => {
  const workflowItems = typeof $items === 'function' ? $items('Workflow Settings', 'main', 0) : null;
  if (workflowItems?.length) {
    return workflowItems[0]?.json || {};
  }
  return ($node?.['Workflow Settings']?.json) || {};
};

const settings = getSettings();
const cloudName = settings.cloudinaryCloud || 'root';
const apiKey = settings.cloudinaryApiKey || '425135831691668';
const apiSecret = settings.cloudinaryApiSecret || '_XQrU97vlItfuA_mjZzGKG3mZZY';

if (typeof httpRequest !== 'function') {
  throw new Error('httpRequest helper unavailable in this Code node runtime');
}

const endpoint = `https://api.cloudinary.com/v1_1/${cloudName}/image/upload`;
const authHeader = 'Basic ' + Buffer.from(`${apiKey}:${apiSecret}`).toString('base64');

const isWebpBuffer = (buffer) => {
  if (!buffer || buffer.length < 16) return false;
  return buffer.toString('ascii', 0, 4) === 'RIFF' && buffer.toString('ascii', 8, 12) === 'WEBP';
};

const ensureWebpExtension = (url) => {
  if (!url) return url;
  if (url.includes('.webp')) return url;
  const [pathPart, queryPart] = url.split('?');
  const lastSlash = pathPart.lastIndexOf('/');
  const lastDot = pathPart.lastIndexOf('.');
  const hasExtension = lastDot > lastSlash;
  const normalizedPath = hasExtension ? pathPart.slice(0, lastDot) : pathPart;
  return `${normalizedPath}.webp${queryPart ? `?${queryPart}` : ''}`;
};

const injectTransformation = (baseUrl, qualityValue) => {
  if (!baseUrl) return null;
  const qualitySegment = `f_webp,q_${qualityValue}`;
  if (baseUrl.includes('/upload/')) {
    const transformed = baseUrl.replace('/upload/', `/upload/${qualitySegment}/`);
    return ensureWebpExtension(transformed);
  }
  const separator = baseUrl.includes('?') ? '&' : '?';
  return ensureWebpExtension(`${baseUrl}${separator}f=webp&q=${qualityValue}`);
};

const getWebpUrl = (uploadData, qualityValue) => {
  if (Array.isArray(uploadData?.eager)) {
    const eagerVariant = uploadData.eager.find((variant) => variant.format === 'webp');
    if (eagerVariant?.secure_url) return eagerVariant.secure_url;
    if (eagerVariant?.url) return eagerVariant.url;
  }
  if ((uploadData?.secure_url && uploadData.secure_url.endsWith('.webp')) || uploadData?.format === 'webp') {
    return uploadData.secure_url;
  }
  if (uploadData?.url && uploadData.url.endsWith('.webp')) {
    return uploadData.url;
  }
  return injectTransformation(uploadData?.secure_url || uploadData?.url, qualityValue);
};

return Promise.all(
  items.map(async (item) => {
    if (item.json.isAnimated) {
      return item;
    }

    const imageUrl = item.json.imageSrc;
    if (!imageUrl) {
      item.json.message = 'Missing imageSrc for Cloudinary conversion';
      item.json.skipUpload = true;
      return item;
    }

    const quality = Number(item.json.webpQuality || 80) || 80;
    const publicId = `${(item.json.productHandle || 'product')}-${item.json.imageId}`;
    const eagerTransformation = `f_webp,q_${quality}`;

    const payload = {
      file: imageUrl,
      public_id: publicId,
      overwrite: 'true',
      invalidate: 'true',
      eager: eagerTransformation,
      eager_async: false,
      format: 'webp',
      quality: String(quality)
    };

    let uploadData;
    try {
      uploadData = await httpRequest.call(this, {
        method: 'POST',
        uri: endpoint,
        headers: {
          Authorization: authHeader
        },
        form: payload,
        json: true
      });
    } catch (error) {
      const status = error?.response?.statusCode ?? error?.statusCode ?? null;
      const responseBody = error?.response?.body;
      let bodySnippet;
      if (typeof responseBody === 'string') {
        bodySnippet = responseBody.slice(0, 500);
      } else if (responseBody) {
        try {
          bodySnippet = JSON.stringify(responseBody).slice(0, 500);
        } catch (serializationError) {
          bodySnippet = '[unserializable response body]';
        }
      }
      const errorMsg = error?.message || (status ? `status ${status}` : 'unknown error');
      item.json.message = `Cloudinary upload failed: ${errorMsg}`;
      item.json.cloudinaryError = errorMsg;
      if (status) item.json.cloudinaryStatus = status;
      if (bodySnippet) item.json.cloudinaryResponse = bodySnippet;
      item.json.skipUpload = true;
      item.json.webpSizeBytes = 0;
      return item;
    }

    const webpUrl = getWebpUrl(uploadData, quality);
    if (!webpUrl) {
      item.json.message = 'Cloudinary response missing webp variant';
      item.json.skipUpload = true;
      item.json.webpSizeBytes = 0;
      return item;
    }

    let webpBuffer;
    try {
      const binaryResponse = await httpRequest.call(this, {
        method: 'GET',
        uri: webpUrl,
        encoding: null
      });
      webpBuffer = Buffer.from(binaryResponse);
    } catch (error) {
      item.json.message = `Cloudinary download failed: ${error.message}`;
      item.json.skipUpload = true;
      item.json.webpSizeBytes = 0;
      return item;
    }

    if (!isWebpBuffer(webpBuffer)) {
      item.json.message = 'Cloudinary returned non-WebP payload';
      item.json.skipUpload = true;
      item.json.webpSizeBytes = 0;
      return item;
    }

    item.binary = item.binary || {};
    item.binary.webp = {
      data: webpBuffer.toString('base64'),
      mimeType: 'image/webp',
      fileName: `${publicId}.webp`
    };

    item.json.webpSizeBytes = webpBuffer.length;
    item.json.message = `Converted image ${item.json.imageId} via Cloudinary`;
    item.json.skipUpload = false;
    item.json.webpUrl = webpUrl;

    return item;
  })
);

const items = $input.all();
return items.map(item => ({
  json: {
    status: 'updated',
    productId: item.json.productId,
    imageId: item.json.imageId,
    productHandle: item.json.productHandle,
    message: item.json.message || 'Converted to WebP and uploaded',
    webpSizeBytes: item.json.webpSizeBytes
  }
}));
